{"source":"import json
import sys
from datetime import datetime, timezone

def solve():
    if len(sys.argv) < 2:
        return

    try:
        with open(sys.argv[1], 'r') as f:
            data = json.load(f)

        # Handle the weird wrapper if present
        if isinstance(data, dict) and 'content' in data and isinstance(data['content'], str):
            try:
                data = json.loads(data['content'])
            except json.JSONDecodeError:
                pass

        as_of_str = data.get('as_of')
        if not as_of_str:
            print(json.dumps([]))
            return

        as_of_dt = datetime.fromisoformat(as_of_str.replace('Z', '+00:00'))
        if as_of_dt.tzinfo is None:
            # Prompt says as_of is offset-aware.
            pass

        reminders = data.get('reminders', [])
        results = []

        for r in reminders:
            if r.get('completed') is True:
                continue

            due_val = r.get('due')
            if due_val is None:
                continue

            try:
                # Python 3.11+ handles 'Z' but let's be safe with replace
                due_dt = datetime.fromisoformat(due_val.replace('Z', '+00:00'))

                # Check if naive
                if due_dt.tzinfo is None or due_dt.tzinfo.utcoffset(due_dt) is None:
                    continue

                if due_dt <= as_of_dt:
                    results.append({
                        'id': r['id'],
                        'title': r['title'],
                        'due_dt': due_dt,
                        'due_utc': due_dt.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
                    })
            except (ValueError, TypeError):
                continue

        # Sort by due_dt then id
        results.sort(key=lambda x: (x['due_dt'], x['id']))

        # Final output format
        output = []
        for res in results:
            output.append({
                'id': res['id'],
                'title': res['title'],
                'due_utc': res['due_utc']
            })

        print(json.dumps(output))

    except Exception:
        # If anything goes wrong, return empty array as per contract?
        # The prompt says "Empty reminders yields []".
        print(json.dumps([]))

if __name__ == "__main__":
    solve()
